/**
 * Minimal monoline stroke font (lowercase + digits + a few marks) so on-screen UI text can live
 * INSIDE tonal models (one stroked path per string) and survive every renderer.
 * Glyph space: baseline y=0, x-height 1 (y=-1), ascender -1.42, descender +0.42.
 */
type Pt = [number, number];
type Stroke = Pt[];

const arc = (cx: number, cy: number, rx: number, ry: number, a0: number, a1: number, n = 14): Stroke =>
  Array.from({length: n + 1}, (_, i) => {
    const a = ((a0 + ((a1 - a0) * i) / n) * Math.PI) / 180;
    return [cx + Math.cos(a) * rx, cy + Math.sin(a) * ry];
  });
const O = (cx: number, rx = 0.42): Stroke => arc(cx, -0.5, rx, 0.5, 0, 360, 22);

