const f1 = (n: number) => (Math.round(n * 10) / 10).toString();

/** Stroke centre-lines of a string in local units (for stroke-to-fill). */
export const textLines = (s: string, x: number, y: number, size: number, tracking = 0.2): [[number, number][][], number] => {
  let cx = x;
  const out: [number, number][][] = [];
  for (const ch of s.toLowerCase()) {
    const g = G[ch] ?? G[' '];
    g[1].forEach((st) => {
      if (st.length) out.push(st.map(([px, py]) => [cx + px * size, y + py * size] as [number, number]));
    });
    cx += (g[0] + tracking) * size;
  }
  return [out, cx - x - tracking * size];
};

/** Stroke a string into SVG path data. `size` = x-height in local units. Returns [d, width]. */
export const strokeText = (s: string, x: number, y: number, size: number, tracking = 0.2): [string, number] => {
  const [lines, w] = textLines(s, x, y, size, tracking);
  const d = lines.map((st) => 'M ' + st.map(([px, py]) => `${f1(px)} ${f1(py)}`).join(' L ')).join(' ');
  return [d, w];
};

export const textWidth = (s: string, size: number, tracking = 0.2) => strokeText(s, 0, 0, size, tracking)[1];
